    setEditing(p.id);
    setVersion(p.version);
    setName(p.name);
    setGrade(gradeOn(p, today));
    setGradeFrom('');
    setTerms(p.terms === null ? '' : String(p.terms));
    setContact(p.contact ?? '');
    setTags(p.tags.join(', '));
  };
  const cancel = () => {
    clearError();
    setEditing(null);
    setName('');
    setGrade('A');
    setGradeFrom('');
    setTerms('');
    setContact('');
    setTags('');
  };

  return (
    <section data-testid="people-panel">
      <h2>People</h2>
      <form
        data-testid="person-form"
        onSubmit={(e) => {
          e.preventDefault();
          if (name.trim() === '') {
            // Refused here, before anything is sent: the store and the audit file are untouched.
            save.reset();
            setBlank(true);
            return;
          }
          setBlank(false);
          submitOnce(() => save.mutateAsync({ id: editing, name, grade, gradeFrom: gradeFrom.trim(), terms: terms.trim(), contact: contact.trim(), tags, version }));
        }}
      >
        <label>
          Name{' '}
          <input
            data-testid="person-form-name"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <label>
          Grade{' '}
          <select
            data-testid="person-form-grade"
            value={grade}
            onChange={(e) => {
              setGrade(e.target.value);
              clearError();
            }}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          From{' '}
          <input
            data-testid="person-form-grade-from"
            placeholder={today || 'yyyy-mm-dd'}
            value={gradeFrom}
            onChange={(e) => {
              setGradeFrom(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <label>
          Terms{' '}
          <input
            data-testid="person-form-terms"
            placeholder="days"
            size={5}
            value={terms}
            onChange={(e) => {
              setTerms(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <label>
          Contact{' '}
          <input
            data-testid="person-form-contact"
            value={contact}
            onChange={(e) => {
              setContact(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <label>
          Tags{' '}
          <input
            data-testid="person-form-tags"
            placeholder="a, b"
            value={tags}
            onChange={(e) => {
              setTags(e.target.value);
              clearError();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing === null ? 'Add' : 'Save'}
        </button>
        {editing !== null && (
          <>
            {' '}
            <button type="button" data-testid="person-form-cancel" onClick={cancel}>
              Cancel
            </button>
          </>
        )}
        {(blank || save.isError) && (
          <span data-testid="person-form-error" role="alert">
            {' '}
            {blank
              ? 'A name is required.'
              : save.error instanceof HttpError && save.error.status === 409
                ? 'Someone else saved this person since you opened it; the form now shows what is stored.'
                : 'Could not save this person.'}
          </span>
        )}
      </form>
      <QuickAddBar user={user} sheet={sheet} />
      <ShowRetired />
      <table data-testid="people-list">
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <th>Terms</th>
            <th>Contact</th>
            <th>Tags</th>
            <th />
            <PersonColumns.Slot user={user} sheet={sheet} />
          </tr>
        </thead>
        <tbody>
          {people.map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{gradeOn(p, today)}</td>
              <td data-testid="person-terms">{p.terms ?? ''}</td>
              <td data-testid="person-contact">{p.contact ?? ''}</td>
              <td data-testid="person-tags">{p.tags.join(', ')}</td>
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => open(p)}>
                  Edit
                </button>
              </td>
              <PersonCells.Slot user={user} sheet={sheet} person={p} />
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

